-- Synthetic isolated PostgreSQL fixture. Never run against the connected project.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.user',true),'')::uuid $$;
CREATE FUNCTION public.workers_require_read_scope(uuid) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 IF auth.uid() IS NULL OR coalesce(current_setting('test.workers',true),'true')='false' THEN RAISE EXCEPTION 'WORKERS_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
END $$;
CREATE FUNCTION public.can_view_commercial_map(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce(current_setting('test.map',true),'true')<>'false' $$;
CREATE FUNCTION public.map_has_explicit_capability(uuid,text) RETURNS boolean LANGUAGE sql AS $$ SELECT CASE WHEN $2='map.manage_sales' THEN coalesce(current_setting('test.sales',true),'true')<>'false' ELSE coalesce(current_setting('test.contracts',true),'true')<>'false' END $$;
CREATE FUNCTION public.commercial_buyer_display_name(text,text) RETURNS text LANGUAGE sql AS $$ SELECT coalesce(nullif(btrim($1),''),nullif(btrim($2),'')) $$;
CREATE TABLE map_projects(id uuid PRIMARY KEY,org_id uuid,name text,is_archived boolean DEFAULT false,edition_year int);
CREATE TABLE map_segments(id uuid PRIMARY KEY,project_id uuid,slug text,name text,display_name text,is_active boolean DEFAULT true);
CREATE TABLE map_entities(id uuid PRIMARY KEY,project_id uuid,parent_entity_id uuid,segment_id uuid,classification text,public_identifier text,name text,is_archived boolean DEFAULT false,metadata jsonb DEFAULT '{}');
CREATE TABLE map_entity_geometries(id uuid PRIMARY KEY,entity_id uuid,project_id uuid,is_current boolean DEFAULT true,geometry jsonb);
CREATE TABLE commercial_lots(id uuid PRIMARY KEY,project_id uuid,entity_id uuid,public_identifier text,block text,lot_number text,display_name text,status text,official_area_sqm numeric,archived_at timestamptz,updated_at timestamptz DEFAULT now());
CREATE TABLE commercial_exhibitors(id uuid PRIMARY KEY,org_id uuid,name text,trade_name text);
CREATE TABLE lot_sale_orders(id uuid PRIMARY KEY,project_id uuid,exhibitor_id uuid,buyer_name text,buyer_trade_name text,fees_total numeric,spaces_subtotal numeric,negotiated_total numeric,fee_admin numeric DEFAULT 0,fee_ppci numeric DEFAULT 0,fee_cleaning_license numeric DEFAULT 0,updated_at timestamptz DEFAULT now(),status text DEFAULT 'CONFIRMED',reverted_at timestamptz);
CREATE TABLE lot_sales(id uuid PRIMARY KEY,lot_id uuid,buyer_name text,buyer_trade_name text,negotiated_value numeric,created_at timestamptz,status text,reverted_at timestamptz);
CREATE TABLE lot_sale_order_items(id uuid PRIMARY KEY,order_id uuid,sale_id uuid,lot_id uuid,public_identifier text,official_area_snapshot numeric,item_total numeric,created_at timestamptz,signed_at timestamptz,contract_state text);
CREATE TABLE lot_contracts(id uuid PRIMARY KEY,lot_id uuid,contract_number text,scope text,order_id uuid,is_active boolean,active_version int,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE lot_contract_lots(contract_id uuid,lot_id uuid);
CREATE TABLE lot_contract_versions(id uuid PRIMARY KEY,contract_id uuid,version int,superseded_at timestamptz);
CREATE TABLE map_calibrations(id uuid PRIMARY KEY,project_id uuid,status text,map_units_per_meter numeric,version int);
CREATE TABLE commercial_price_rules(id uuid PRIMARY KEY,project_id uuid,price numeric);
