INSERT INTO map_entities SELECT ('00000000-0000-4000-8000-'||lpad((100+n)::text,12,'0'))::uuid,'00000000-0000-4000-8000-000000000001',
 CASE WHEN n<=10 THEN '00000000-0000-4000-8000-000000000020'::uuid WHEN n<=15 THEN '00000000-0000-4000-8000-000000000021'::uuid WHEN n<=28 THEN '00000000-0000-4000-8000-000000000022'::uuid ELSE '00000000-0000-4000-8000-000000000023'::uuid END,NULL,
 CASE WHEN n<=15 THEN 'INTERNAL_STAND' ELSE 'SELLABLE_LOT' END,'technical-'||n,'Espaço '||n,false,'{"labelAnchor":[0.5,0.5]}' FROM generate_series(1,38)n;
INSERT INTO commercial_lots SELECT ('00000000-0000-4000-8000-'||lpad((200+n)::text,12,'0'))::uuid,'00000000-0000-4000-8000-000000000001',('00000000-0000-4000-8000-'||lpad((100+n)::text,12,'0'))::uuid,'technical-'||n,CASE WHEN n<=10 THEN 'P13' WHEN n<=15 THEN 'P12' WHEN n<=28 THEN 'R' ELSE 'U' END,CASE WHEN n=28 THEN NULL ELSE n::text END,'Lote atual '||n,CASE WHEN n<=5 OR n>=11 AND n<=37 THEN 'SOLD' WHEN n<=10 THEN 'SALE_OPEN' ELSE 'AVAILABLE' END,CASE WHEN n=38 THEN NULL ELSE 25 END,NULL,now() FROM generate_series(1,38)n;
INSERT INTO map_entity_geometries SELECT ('00000000-0000-4000-8000-'||lpad((300+n)::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad((100+n)::text,12,'0'))::uuid,'00000000-0000-4000-8000-000000000001',true,jsonb_build_object('type','Polygon','coordinates',jsonb_build_array(jsonb_build_array(jsonb_build_array(n,0),jsonb_build_array(n+1,0),jsonb_build_array(n+1,1),jsonb_build_array(n,1),jsonb_build_array(n,0)))) FROM generate_series(1,38)n;
